fn mix(x0:u64)u64{var x=x0+%0x9e3779b97f4a7c15;x=(x^(x>>30))*%0xbf58476d1ce4e5b9;x=(x^(x>>27))*%0x94d049bb133111eb;return x^(x>>31);}
fn build(a:std.mem.Allocator,src:[]const u8,bin:[]const u8)!void{var f=try std.fs.createFileAbsolute(src,.{.truncate=true});defer f.close();try f.writeAll(CandidateC);const r=try std.process.Child.run(.{.allocator=a,.argv=&.{"cc",src,"-O2","-lseccomp","-o",bin},.max_output_bytes=4096});defer a.free(r.stdout);defer a.free(r.stderr);if(r.term!=.Exited or r.term.Exited!=0)return error.CandidateCompile;}
fn launch(a:std.mem.Allocator,bin:[]const u8,mode:[]const u8,input:[]const u8)![]u8{const script=try std.fmt.allocPrint(a,"printf '{s}' | exec timeout --signal=KILL 1s prlimit --as=67108864 --cpu=1 --nofile=8:8 -- bwrap --unshare-user --unshare-pid --unshare-ipc --unshare-uts --unshare-net --die-with-parent --new-session --cap-drop ALL --clearenv --ro-bind /usr /usr --ro-bind /lib /lib --ro-bind /lib64 /lib64 --ro-bind {s} /candidate --proc /proc --dev /dev --tmpfs /tmp --tmpfs /work --chdir /work /candidate {s}",.{input,bin,mode});defer a.free(script);const r=try std.process.Child.run(.{.allocator=a,.argv=&.{"bash","-ceu",script},.max_output_bytes=8192});defer a.free(r.stderr);if(r.term!=.Exited or r.term.Exited!=0){a.free(r.stdout);return error.CandidateFailed;}return r.stdout;}
fn parse(out:[]const u8,n:usize,max:usize)?usize{var it=std.mem.tokenizeAny(u8,out," \n\r");if(!std.mem.eql(u8,it.next() orelse return null,"X"))return null;const got=std.fmt.parseInt(usize,it.next() orelse return null,10) catch return null;const p=std.fmt.parseInt(usize,it.next() orelse return null,10) catch return null;if(it.next()!=null or got!=n or p>=max)return null;return p;}
const APolicy=enum{earned_chain,aj4_fixed_allocator,random,replay,shuffled_history,blank_no_relevance,answer_memory_scrubbed,topology_ablation,value_ablation,arbitration_ablation,broad_coverage};
const PPolicy=enum{earned_portfolio,am4_single_record,fixed_broad_coverage,fixed_portfolio_schedule,random,replay,shuffled_history,blank_no_relevance,answer_memory_scrubbed,topology_relevance_ablation,value_ablation,arbitration_ablation,mechanism_misrouting};
const R=struct{contacts:usize=0,material:i64=0,exact:usize=0,accepted:usize=0};
