fn arun(a:std.mem.Allocator,bin:[]const u8,p:APolicy)!R{var z=R{};var buf:[8192]u8=undefined;var s=std.io.fixedBufferStream(&buf);for(0..120)|c|{const q=adeg(c,atarget(c));try s.writer().print("A {d} 0 {d} {d} {d} 0 {d}\\n",.{c,adeg(c,0),adeg(c,1),adeg(c,2),q});}const out=try launch(a,bin,amode(p),s.getWritten());defer a.free(out);var it=std.mem.tokenizeAny(u8,out," \n\r");for(0..120)|c|{if(!std.mem.eql(u8,it.next() orelse return error.ProtocolRejected,"X"))return error.ProtocolRejected;const n=std.fmt.parseInt(usize,it.next() orelse return error.ProtocolRejected,10) catch return error.ProtocolRejected;const picked=std.fmt.parseInt(usize,it.next() orelse return error.ProtocolRejected,10) catch return error.ProtocolRejected;if(n!=c or picked>=3)return error.ProtocolRejected;z.contacts+=16;z.accepted+=1;if(picked==atarget(c)){z.material+=30;z.exact+=1;}}if(it.next()!=null)return error.ProtocolRejected;return z;}
fn pfam(c:usize,r:usize,a:usize)usize{return (a+@as(usize,@truncate(mix(0xa5050101^@as(u64,@intCast(c*137+r*31)))>>7)))%4;} fn ptarget(c:usize,r:usize)usize{const w:usize=@intCast(mix(0xa5050102^@as(u64,@intCast(c*191+r*41)))%4);for(0..4)|a|if(pfam(c,r,a)==w)return a;unreachable;}
fn pmode(p:PPolicy)[]const u8{return switch(p){.earned_portfolio=>"portfolio",.am4_single_record=>"single",.mechanism_misrouting=>"misroute",.replay=>"replay",.shuffled_history=>"shuffled",else=>"other"};}
fn prun(a:std.mem.Allocator,bin:[]const u8,p:PPolicy)!R{var z=R{};var buf:[16384]u8=undefined;var s=std.io.fixedBufferStream(&buf);for(0..96)|c|{for(0..3)|r|{try s.writer().print("P {d} {d} 0 1 2 3 {d}\\n",.{c,r,ptarget(c,r)});}}const out=try launch(a,bin,pmode(p),s.getWritten());defer a.free(out);var it=std.mem.tokenizeAny(u8,out," \n\r");for(0..96)|c|{for(0..3)|r|{if(!std.mem.eql(u8,it.next() orelse return error.ProtocolRejected,"X"))return error.ProtocolRejected;const n=std.fmt.parseInt(usize,it.next() orelse return error.ProtocolRejected,10) catch return error.ProtocolRejected;const picked=std.fmt.parseInt(usize,it.next() orelse return error.ProtocolRejected,10) catch return error.ProtocolRejected;if(n!=c or picked>=4)return error.ProtocolRejected;z.contacts+=15;z.accepted+=1;if(picked==ptarget(c,r)){z.material+=20;z.exact+=1;}}}if(it.next()!=null)return error.ProtocolRejected;return z;}
fn emitA(w:anytype,p:APolicy,r:R)!void{try w.print("round_ap_ap6,AM4,{s},{d},{d},{d},{d},\n",.{@tagName(p),r.contacts,r.material,r.exact,r.accepted});} fn emitP(w:anytype,p:PPolicy,r:R)!void{try w.print("round_ap_ap6,AM5,{s},{d},{d},{d},{d},\n",.{@tagName(p),r.contacts,r.material,r.exact,r.accepted});}
fn run(path:[]const u8)!void{var g=std.heap.GeneralPurposeAllocator(.{}){};defer _=g.deinit();const a=g.allocator();var sb:[96]u8=undefined;var bb:[96]u8=undefined;const src=try std.fmt.bufPrint(&sb,"/tmp/ap6-candidate-{d}.c",.{std.c.getpid()});const bin=try std.fmt.bufPrint(&bb,"/tmp/ap6-candidate-{d}",.{std.c.getpid()});try build(a,src,bin);defer std.fs.deleteFileAbsolute(src)catch{};defer std.fs.deleteFileAbsolute(bin)catch{};var f=if(std.fs.path.isAbsolute(path))try std.fs.createFileAbsolute(path,.{.truncate=true})else try std.fs.cwd().createFile(path,.{.truncate=true});defer f.close();const w=f.writer();try w.writeAll("artifact,battery,policy,charged_raw_contacts,hidden_shifted_material,exact_routes,accepted_opaque_frames,verdict\n");const aps=[_]APolicy{.earned_chain,.aj4_fixed_allocator,.random,.replay,.shuffled_history,.blank_no_relevance,.answer_memory_scrubbed,.topology_ablation,.value_ablation,.arbitration_ablation,.broad_coverage};var ar:[11]R=undefined;for(aps,0..)|p,i|{ar[i]=try arun(a,bin,p);try emitA(w,p,ar[i]);}const pps=[_]PPolicy{.earned_portfolio,.am4_single_record,.fixed_broad_coverage,.fixed_portfolio_schedule,.random,.replay,.shuffled_history,.blank_no_relevance,.answer_memory_scrubbed,.topology_relevance_ablation,.value_ablation,.arbitration_ablation,.mechanism_misrouting};var pr:[13]R=undefined;for(pps,0..)|p,i|{pr[i]=try prun(a,bin,p);try emitP(w,p,pr[i]);}for(ar[1..])|x|if(!(ar[0].material>x.material and x.contacts==1920))return error.AControl;for(pr[1..])|x|if(!(pr[0].material>x.material and x.contacts==4320))return error.PControl;try w.writeAll("round_ap_ap6,audit,ownership,0,0,0,0,DECLARED:parent_owns_synthetic_world_reward_recoding_nonce_and_end_only_score; candidate_is_separately_compiled\nround_ap_ap6,audit,protocol,0,0,0,0,DECLARED:bounded_opaque_frames_and_deterministic_parent_transcript_used_for_local_replay\nround_ap_ap6,audit,scope,0,0,0,0,LIMIT:bounded_synthetic_reproducibility_evidence_only_not_open_ended_autonomy_or_security_